from math import factorial

def check(n):
    denom = 2*n - 1
    if denom == 0:
        return False
    # We want 3 * ((n+2)! + 1) % denom == 0
    # Since denom is always odd, 3 * ((n+2)! + 1) % denom == 0 is same as
    # ((n+2)! + 1) % denom == 0 if 3 and denom are coprime.
    # If 3 divides denom, then denom = 3 * m.
    # Then 3 * ((n+2)! + 1) is divisible by 3 * m iff (n+2)! + 1 is divisible by m.

    # Let's just compute it directly for small n.
    try:
        res = (3 * (factorial(n + 2) + 1)) % abs(denom)
        return res == 0
    except OverflowError:
        return False

for n in range(200):
    if check(n):
        print(f"n={n}")

