def check_large_n(n):
    denom = 2*n - 1
    if denom == 0:
        return False
    p = abs(denom)
    if p == 1:
        return True
    fact_mod = 1
    for i in range(1, n + 3):
        fact_mod = (fact_mod * i) % p
    return (3 * (fact_mod + 1)) % p == 0

for n in range(10000):
    if check_large_n(n):
        print(f"n={n}")
